from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
color_sensor = ColorSensor(Port.E)
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.B, Direction.CLOCKWISE)
Ben = DriveBase(Left, Right, 56, 114)


# The main program starts here.
while color_sensor.reflection() >= 30:
    Ben.drive(100, 0)
    print(color_sensor.reflection(), 'while driving')
prime_hub.speaker.beep(1000, 100)
Ben.straight(0)
print(color_sensor.reflection(), 'at stop')
